// cli_tool: runs an MNIST MLP (784 -> 16 -> 16 -> 10) inference.
// Usage: ./cli_tool weights.json image.png
// Prints only the predicted digit (0-9).
//
// Weights are loaded from weights.json (a plain JSON document, parsed with cJSON).
// Images are decoded with lodepng (supports any PNG color type, resized to 28x28).

#include "cJSON.h"
#include "lodepng.h"

#include <cmath>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <fstream>
#include <string>
#include <vector>

static bool read_file(const std::string &path, std::string &out) {
    std::ifstream f(path, std::ios::binary);
    if (!f) return false;
    f.seekg(0, std::ios::end);
    std::streamsize size = f.tellg();
    f.seekg(0, std::ios::beg);
    if (size < 0) return false;
    out.resize((size_t)size);
    if (size > 0 && !f.read(&out[0], size)) return false;
    return true;
}

// Parse a JSON array of numbers into a C-style vector.
static bool parse_float_array(const cJSON *arr, std::vector<float> &out) {
    if (!cJSON_IsArray(arr)) return false;
    out.clear();
    const cJSON *it = nullptr;
    cJSON_ArrayForEach(it, arr) {
        if (!cJSON_IsNumber(it)) return false;
        out.push_back((float)it->valuedouble);
    }
    return true;
}

struct Layer {
    int in_dim = 0;
    int out_dim = 0;
    bool relu = true;
    std::vector<float> weight;  // row-major, shape [out_dim][in_dim]
    std::vector<float> bias;    // [out_dim]
};

static bool load_model(const std::string &path, std::vector<Layer> &layers) {
    std::string text;
    if (!read_file(path, text)) return false;
    cJSON *root = cJSON_Parse(text.c_str());
    if (!root) return false;
    layers.clear();
    cJSON *jlayers = cJSON_GetObjectItemCaseSensitive(root, "layers");
    if (!cJSON_IsArray(jlayers)) { cJSON_Delete(root); return false; }
    const cJSON *jl = nullptr;
    cJSON_ArrayForEach(jl, jlayers) {
        Layer L;
        cJSON *jin = cJSON_GetObjectItemCaseSensitive(jl, "in");
        cJSON *jout = cJSON_GetObjectItemCaseSensitive(jl, "out");
        cJSON *jact = cJSON_GetObjectItemCaseSensitive(jl, "activation");
        cJSON *jw = cJSON_GetObjectItemCaseSensitive(jl, "weight");
        cJSON *jb = cJSON_GetObjectItemCaseSensitive(jl, "bias");
        if (!cJSON_IsNumber(jin) || !cJSON_IsNumber(jout) || !jact ||
            !parse_float_array(jw, L.weight) || !parse_float_array(jb, L.bias)) {
            cJSON_Delete(root);
            return false;
        }
        L.in_dim = (int)jin->valueint;
        L.out_dim = (int)jout->valueint;
        L.relu = std::strcmp(jact->valuestring, "relu") == 0;
        if ((size_t)L.in_dim * L.out_dim != L.weight.size() ||
            L.bias.size() != (size_t)L.out_dim) {
            cJSON_Delete(root);
            return false;
        }
        layers.push_back(std::move(L));
    }
    cJSON_Delete(root);
    return !layers.empty();
}

// Resize a grayscale image to 28x28 (nearest neighbor; works fine for 28x28 inputs).
static std::vector<float> to_input(const unsigned char *px, int w, int h, int &err) {
    (void)err;
    std::vector<float> img(784, 0.0f);
    if (w <= 0 || h <= 0) return img;
    for (int y = 0; y < 28; y++) {
        int sy = y * h / 28;  // nearest-neighbor sample
        if (sy < 0) sy = 0;
        if (sy >= h) sy = h - 1;
        for (int x = 0; x < 28; x++) {
            int sx = x * w / 28;
            if (sx < 0) sx = 0;
            if (sx >= w) sx = w - 1;
            int v = px[(size_t)sy * w + sx];  // 0..255, 0 = black
            img[y * 28 + x] = v / 255.0f;
        }
    }
    return img;
}

int main(int argc, char **argv) {
    if (argc != 3) {
        std::fprintf(stderr, "usage: %s weights.json image.png\n", argv[0]);
        return 1;
    }

    std::vector<Layer> layers;
    if (!load_model(argv[1], layers)) {
        std::fprintf(stderr, "error: failed to load weights from %s\n", argv[1]);
        return 1;
    }

    unsigned char *px = nullptr;
    int w = 0, h = 0, err = lodepng_decode32_file(&px, &w, &h, argv[2]);
    if (err) {
        std::fprintf(stderr, "error: lodepng decode error %u: %s\n", err,
                     lodepng_error_text(err));
        return 1;
    }
    std::vector<float> x = to_input(px, w, h, err);
    free(px);

    for (const Layer &L : layers) {
        std::vector<float> y((size_t)L.out_dim, 0.0f);
        for (int o = 0; o < L.out_dim; o++) {
            const float *row = &L.weight[(size_t)o * L.in_dim];
            float s = L.bias[o];
            for (int i = 0; i < L.in_dim; i++) s += row[i] * x[i];
            if (L.relu && s < 0.0f) s = 0.0f;
            y[o] = s;
        }
        x = std::move(y);
    }

    int best = 0;
    for (int i = 1; i < (int)x.size(); i++) {
        if (x[i] > x[best]) best = i;
    }
    std::printf("%d\n", best);
    return 0;
}

